func (e LinkEl) Child(child Element) LinkEl { tParentElementChild(e.n, child); return e }

// Add multiple child elements to this element.
func (e LinkEl) Children(children ...Element) LinkEl {
	tParentElementChildren(e.n, children...)
	return e
}
